def norm(s):
    s = unicodedata.normalize('NFKC', str(s))
    s = re.sub(r'[‐-―−­]', '-', s)
    return re.sub(r'\s+', ' ', s).strip().lower()


def squash(s):
    return re.sub(r'[\s\-]', '', norm(s))


def main(text_dir, out):
    texts = {}
    for p in Path(text_dir).glob('*.txt'):
        texts[p.stem] = p.read_text(encoding='utf-8')

    def verify(paper, file, quote):
        if not quote:
            return '无原句', ''
        key = paper if file == '正文' else f'{paper}_SI'
        t = texts.get(key, '')
        if quote in t:
            return '程序核验通过', '✅'
        if norm(quote) in norm(t):
            return '程序核验通过（空白/字符规范化后）', '✅'
        if squash(quote) in squash(t):
            return '程序核验通过（跨行或断字拼接后）', '✅'
        return '原文未找到', '❌'

    def page(rows, cols, idcol):
        df = pd.DataFrame(rows, columns=cols)
        df.insert(1, '论文', df[idcol].str[:2])
        res = df.apply(lambda r: pd.Series(verify(r['论文'], r['文件'], r['原句'])), axis=1)
        df['核验状态'], df['显示'] = res[0], res[1]
        df['复核 ✍'] = ''
        return df

    sam = page(SAMPLES, ['样品号', '文中样品名', '样品类型', '实验配置', '正极组成（比例基准）', '电解质（隔膜层）', '负极', '施加的策略', '加工', '尺寸', '未报告或待核查', '文件', '页码', '图表', '原句'], '样品号')
    tst = page(TESTS, ['测试号', '样品号', '重复/电池编号', '测试方法', '本电池载量', '运行压力', '温度', '电流程序', '电位窗口', '循环阶段/取值点', '未报告或待核查', '文件', '页码', '图表', '原句'], '测试号')
    cmp_ = page(COMPARISONS, ['比较号', '样品测试号', '对照测试号', '对照来源', '实际变化', '单因素', '测试条件核对', '指标', '样品值', '对照值', '单位', '取值点', '重复数', '误差或不确定性', '观察方向', '目标意义', '值来源', '需人看的原因', '文件', '页码', '图表', '原句'], '比较号')
    stg = page(STRATEGIES, ['策略号', '策略家族', '具体实现', '位置', '针对的问题', '声称作用', '支持作用的比较', '支持层次', '作用所需前提', '前提提出者', '前提的支持证据', '代价或限制', '代价证据', '跨体系相关陈述', '文件', '页码', '原句'], '策略号')

    # 显示标记：计算 → 🧮；有"需人看的原因"或单元格含【读图】【待核查】→ 🔶；原文未找到 → ❌
    def mark(df, extra_cols=()):
        out = []
        for _, r in df.iterrows():
            if r['显示'] == '❌':
                out.append('❌')
            elif r.get('值来源', '') == '计算':
                out.append('🧮')
            elif any(isinstance(r[c], str) and r[c].strip() for c in extra_cols) or any('【读图' in str(v) or '【待核查' in str(v) for v in r.values):
                out.append('🔶')
            else:
                out.append('✅')
        df['显示'] = out
    mark(sam, ['未报告或待核查'])
    mark(tst, ['未报告或待核查'])
    mark(cmp_, ['需人看的原因'])
    mark(stg)

    # 策略页"实验条件组合"：代码从测试页汇总（列出实际测过的组合，不当连续范围）
    def combos(sid):
        smp = sam[sam['施加的策略'].str.contains(sid, regex=False)]['样品号']
        t = tst[tst['样品号'].isin(smp)]
        if t.empty:
            return '—'
        parts = t.apply(lambda r: f"{r['测试号']}：{r['温度']}｜{r['运行压力']}｜{r['电流程序']}｜{r['电位窗口']}", axis=1)
        return '\n'.join(parts)
    stg.insert(stg.columns.get_loc('作用所需前提'), '实验条件组合（代码汇总）', stg['策略号'].map(combos))

    jud = pd.DataFrame(JUDGMENTS, columns=['判定号', '策略号', '来源组', '目标配置', '比较级别', '类比依据与差异', '前提逐项核对', '固态锂硫应用情况', '稳定性说明', '代价证据', '判定', '待检验的问题', '依据（比较号）'])
    jud['复核 ✍'] = ''
    com = pd.DataFrame(COMBOS, columns=['假设号', '策略甲', '策略乙', '目标配置', '能否独立操控', '假设内容', '文献依据', '实验组', '指标 Y（方向、尺度）', '重复数', '需要的机制表征'])
    com['复核 ✍'] = ''
    pap = pd.DataFrame(PAPERS, columns=['论文', '组', 'DOI', '简述'])
    fq = pd.DataFrame(FIELD_QUESTIONS, columns=['编号', '要你定的字段问题'])
    fq['你的决定 ✍'] = ''
    note = pd.DataFrame({'说明': [
        '方案D §9.2 全文表样（5 篇，2026-10-18）。数据结构按方案D §8 试点数据结构 v0.1。',
        '三层不增强：比较页只写观察；策略页写作者解释；判定页、组合假设页写分析者的新假设。',
        '单元格里的【未报告】= 已查阅正文和 SI 都没写；【待核查】= 需要人再看；【不适用】。',
        '"原句"由代码到 PDF 转出的文本里逐字核对（允许空白、断字、连字差异）。显示：✅ 找到 ｜🧮 计算/模拟值 ｜🔶 需人看（读图、待核查、跨论文、取值点不可比等）｜❌ 原文未找到。',
        '"实验条件组合"由代码从测试页汇总，列出实际测过的条件，不当作连续有效范围。',
        '要你定的字段问题见最后一页 Z1–Z9。',
    ]})

    with pd.ExcelWriter(out, engine='openpyxl') as w:
        for name, df in [('说明', note), ('论文', pap), ('样品', sam), ('测试', tst), ('比较', cmp_), ('策略', stg), ('判定', jud), ('组合假设', com), ('字段问题', fq)]:
            df.to_excel(w, name, index=False)
        for ws in w.book.worksheets:
            ws.freeze_panes = 'B2'
            for col in ws.columns:
                width = max(len(str(c.value)) if c.value is not None else 0 for c in col[:80])
                c0 = col[0].column
                letter = c0 if isinstance(c0, str) else get_column_letter(c0)
                ws.column_dimensions[letter].width = min(max(8, width * 1.1), 50)

    allq = pd.concat([sam[['样品号', '显示', '核验状态', '原句']].rename(columns={'样品号': '号'}),
                      tst[['测试号', '显示', '核验状态', '原句']].rename(columns={'测试号': '号'}),
                      cmp_[['比较号', '显示', '核验状态', '原句']].rename(columns={'比较号': '号'}),
                      stg[['策略号', '显示', '核验状态', '原句']].rename(columns={'策略号': '号'})])
    print('行数：样品', len(sam), '｜测试', len(tst), '｜比较', len(cmp_), '｜策略', len(stg), '｜判定', len(jud), '｜组合假设', len(com))
    print('原句核验：', allq['核验状态'].value_counts().to_dict())
    print('显示标记：', allq['显示'].value_counts().to_dict())
    bad = allq[allq['显示'] == '❌']
    if len(bad):
        print('未找到：'); print(bad[['号', '原句']].to_string())


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
